-- ── branches ────────────────────────────────────────────────────────────────
-- El horario se arma desde (apertura, cierre, abre_domingo) en vez de escribir
-- los 7 días por sucursal: son 56 objetos que nadie va a leer y que solo
-- existen para que las pantallas no encuentren un NULL.
--
-- `settings` conserva la ubicación (los mapas del portal la usan) y descarta el
-- resto — en particular la lista `legal.nurses`, que son UUID de empleados que
-- en un entorno de pruebas no existen.
INSERT INTO public.branches (id, name, address, phone, cell, type, opening_date,
                             weekly_hours, settings, conteo_ciclico_activo, conteo_ciclico_tamano)
SELECT v.id, v.name, v.address, v.phone, v.cell, v.type, v.opening_date::date,
       (SELECT jsonb_object_agg(d::text,
                 CASE WHEN d = 0 AND NOT v.abre_domingo
                      THEN jsonb_build_object('start', '',        'end', '',       'isOpen', false)
                      ELSE jsonb_build_object('start', v.apertura, 'end', v.cierre, 'isOpen', true)
                 END)
          FROM generate_series(0, 6) d),
       jsonb_build_object(
         'rent',     '{}'::jsonb,
         'legal',    '{}'::jsonb,
         'services', '{}'::jsonb,
         'location', jsonb_build_object('lat', v.lat, 'lng', v.lng,
                                        'department',   'Chalatenango',
                                        'municipality', v.municipio)),
       v.conteo_activo, 200
FROM (VALUES
  (2,  'La Popular',      '1ra. Av. Norte, Barrio El Centro, Agua Caliente',              '2301-0013', '7962-0372', 'FARMACIA',       '1987-05-02', '07:00', '19:00', true,  14.18625339790212, -89.22778604630774, 'Chalatenango Centro', true),
  (4,  'Salud 1',         '4ta. Calle Oriente #3, Barrio San Antonio',                    '2301-0013', '7803-0027', 'FARMACIA',       '2010-06-01', '07:00', '22:00', true,  14.040614677110216, -88.93690718535933, 'Chalatenango Sur',   true),
  (25, 'Salud 2',         'Calle Morazán No. 39, Barrio El Calvario',                     '2309-0533', '7961-9622', 'FARMACIA',       '2020-01-01', '07:00', '19:00', true,  14.043229,          -88.935683,         'Chalatenango Sur',   true),
  (27, 'Salud 3',         'Carr. a Chalatenango, Crio. Totolco',                          '2301-0013', '7962-0366', 'FARMACIA',       '2023-01-01', '07:00', '21:00', true,  14.04118476462897,  -88.96314613087684, 'Chalatenango Sur',   true),
  (28, 'Salud 4',         'Calle Colón y Ave. Morazán, Barrio El Centro, El Paraiso',     '2301-0013', '7962-2719', 'FARMACIA',       '2020-02-01', '07:00', '21:00', true,  14.106492047689937, -89.06847091966127, 'Chalatenango Sur',   true),
  (29, 'Salud 5',         '3ra.av.sur y 2da.cll.pte, Barrio El Carmen, Nueva Concepción', '2301-0013', '7842-9291', 'FARMACIA',       '2024-10-01', '07:00', '19:00', true,  14.128001164569541, -89.29326452325331, 'Chalatenango Centro', true),
  (30, 'Bodega',          'Bodega, Carr. a Chalatenango, Crio. Totolco',                  '2301-0013', '7961-6499', 'BODEGA',         '2026-03-17', '08:00', '17:00', false, 14.041176958447284, -88.96311126213165, 'Chalatenango Sur',   false),
