) AS v(id, name, address, phone, cell, type, opening_date, apertura, cierre, abre_domingo, lat, lng, municipio, conteo_activo)
ON CONFLICT (id) DO NOTHING;

-- ── secuencias ──────────────────────────────────────────────────────────────
-- Sin esto, el primer alta desde la pantalla intenta el id 1 y choca contra las
-- filas sembradas. Sale del catálogo (`pg_get_serial_sequence`) para no fallar
-- si la columna no es serial.
--
-- SOLO SUBE, NUNCA BAJA. Un `setval(seq, max(id))` a secas es seguro en un
-- branch recién sembrado pero PELIGROSO en producción: si ahí la secuencia ya
-- avanzó por encima del máximo vigente (pasa en cuanto se borra la última fila,
-- o si un INSERT falló después de consumir el número), retrocederla hace que el
-- próximo alta repita un id que ya se usó. Como esta migración también corre
-- contra prod —donde es no-op para los datos— la guarda no es opcional.
DO $$
DECLARE s text; seq text; actual bigint; maximo bigint;
BEGIN
  FOREACH s IN ARRAY ARRAY['public.roles', 'public.branches'] LOOP
    seq := pg_get_serial_sequence(s, 'id');
    IF seq IS NOT NULL THEN
      EXECUTE format('SELECT COALESCE(max(id), 0) FROM %s', s) INTO maximo;
      EXECUTE format('SELECT last_value FROM %s', seq)         INTO actual;
      IF maximo > actual THEN
        PERFORM setval(seq, maximo);
      END IF;
    END IF;
  END LOOP;
END $$;

